import{z as l,x as i,o as n,c as p,q as B,j as r,D as e,d as t,s as o,S as s,b as a}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"ETF 期权市场","description":"","frontmatter":{"title":"ETF 期权市场","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/cn-etf-options.md","filePath":"quant/cn-etf-options.md","lastUpdated":1791063341000}'),d={name:"quant/cn-etf-options.md"};function T(F,E,u,C,h,m){const A=i("Mermaid");return n(),p("div",null,[E[2]||(E[2]=B('<h1 id="etf-期权市场" tabindex="-1">ETF 期权市场 <a class="header-anchor" href="#etf-期权市场" aria-label="Permalink to &quot;ETF 期权市场&quot;">​</a></h1><div class="epigraph"><p>上交所 50ETF 期权把波动率写成可交易合约；之后 300ETF 等品种把指数波动从期货基差里拆出一截。合约是欧式、有涨跌停与保证金，不是 OTC 权证。</p><footer>—— 上海证券交易所股票期权试点交易规则及合约细则；深圳证券交易所上市期权相关规则；对照[期权到期流程](/quant/options-expiration-process)</footer></div><p><a href="/quant/cn-index-basis-hedge-cost">上一课</a>的对冲工具主要是期货。本课的缺口是<strong>场内 ETF 期权</strong>：2015 年上交所上证 50ETF 期权试点，其后沪深 300ETF 期权等扩展了行权价与到期月。到期、行权、保证金与涨跌停按期权细则，与股票 T+1 不同。不重写 Black–Scholes 推导；只写 A 股场内期权如何改变中性与增强的可行集。后课商品期权换标的与时段。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>期货对冲留下基差与 gamma=0 的线性暴露。ETF 期权提供凸性：保护性看跌、领口、备兑，以及波动率买卖。问题是制度：合约单位、做市义务、涨跌停、保证金、到期日与行权（欧式现金或证券交割以合约为准）、投资者适当性。用美股上市期权的假设（T+1 股票交割、无涨跌停、连续行权价）会算错 A 股执行与风险。</p><p><span class="marginnote">「欧式」指只能在到期日当天行权，不是「欧洲的期权」；到期前随时能行权的叫美式。A 股 ETF 期权是欧式，意味着存续期内想离场只能卖出平仓，不能提前把权利兑换成现货。</span></p><p>流动性集中在近月、近价、主力 ETF。远月与虚值的买卖价差可以吃掉理论边缘。隐含波动率曲面在 2015、2018、2020 等压力期与股指期货贴水同时移动，但两者不是同一风险：一个是凸性价格，一个是线性对冲拥挤。</p><h3 id="与-etf-申赎、现货涨跌停的联立" tabindex="-1">与 ETF 申赎、现货涨跌停的联立 <a class="header-anchor" href="#与-etf-申赎、现货涨跌停的联立" aria-label="Permalink to &quot;与 ETF 申赎、现货涨跌停的联立&quot;">​</a></h3><p>期权定价锚是 ETF 与 IOPV，而 ETF 相对篮子可折溢价，篮子成分可涨跌停，见<a href="/quant/cn-etf-creation">ETF 申赎</a>。期权做市的对冲可能在成分涨停时无法买齐，希腊字母对冲失败。这是产品风险，不是模型 σ 估错。到期日若遇成分停牌或涨跌停，交割与结算安排以交易所公告为准，回测不得假设完美复制。</p><p><span class="marginnote">期权卖方保证金与股票两融保证金是两套。组合保证金优惠以交易所与会员规则为准，不可把 SPAN 数字从商品所直接套到 ETF 期权。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>合约主数据：标的 ETF、乘数、到期、行权方式、涨跌停公式、交易时段。波动率研究用可成交的买卖报价，不用中间价假成交。对冲模拟加入 ETF 涨跌停与篮子可复制约束。到期流程用本栏到期课的状态机，日历换成上交所/深交所期权日历。适当性：策略客户若不能开期权仓，该工具从 universes 删除。</p><p><span class="marginnote">合约单位通常是 10000 份：买 1 张认购期权，行权时按行权价买入的是 10000 份 ETF，不是 1 份。仓位要按「张数 × 合约单位 × 标的价格」估算名义市值，一张合约动辄几十万元名义，按「张」想仓位会严重低估暴露。</span></p><p>与中性产品：用看跌保护替代部分期货空头，改变的是凸性与权利金，不是消灭基差——现货–期货–期权三者仍可联立套利，但受涨跌停切断。</p><p>三种常见凸性结构各自留下什么暴露，可以放在一起看：</p>',15)),(n(),r(s,null,{default:e(()=>[o(A,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20TD%0A%20%20SPOT%5B%22%E6%8C%81%E6%9C%89%20ETF%20%E7%8E%B0%E8%B4%A7%22%5D%20--%3E%20PRO%5B%22%E5%8A%A0%E4%B9%B0%E8%AE%A4%E6%B2%BD%EF%BC%9A%E4%BF%9D%E6%8A%A4%E6%80%A7%E7%9C%8B%E8%B7%8C%22%5D%0A%20%20SPOT%20--%3E%20COL%5B%22%E5%8A%A0%E4%B9%B0%E8%AE%A4%E6%B2%BD%E5%B9%B6%E5%8D%96%E8%AE%A4%E8%B4%AD%EF%BC%9A%E9%A2%86%E5%8F%A3%22%5D%0A%20%20SPOT%20--%3E%20COV%5B%22%E5%8A%A0%E5%8D%96%E8%AE%A4%E8%B4%AD%EF%BC%9A%E5%A4%87%E5%85%91%22%5D%0A%20%20PRO%20--%3E%20R1%5B%22%E4%B8%8B%E8%A1%8C%E6%9C%89%E4%BF%9D%E5%BA%95%20%E4%B8%8A%E8%A1%8C%E4%BF%9D%E7%95%99%20%E4%BB%98%E6%9D%83%E5%88%A9%E9%87%91%22%5D%0A%20%20COL%20--%3E%20R2%5B%22%E4%B8%8B%E8%A1%8C%E6%9C%89%E5%BA%95%20%E4%B8%8A%E8%A1%8C%E5%B0%81%E9%A1%B6%20%E6%9D%83%E5%88%A9%E9%87%91%E8%BF%91%E4%BC%BC%E6%8A%B5%E6%B6%88%22%5D%0A%20%20COV%20--%3E%20R3%5B%22%E6%94%B6%E6%9D%83%E5%88%A9%E9%87%91%E5%A2%9E%E5%8E%9A%20%E4%B8%8B%E8%A1%8C%E9%A3%8E%E9%99%A9%E4%B8%8D%E5%87%8F%22%5D%0A%20%20JUMP%5B%22%E6%B6%A8%E8%B7%8C%E5%81%9C%E4%B8%8E%E8%B7%B3%E7%A9%BA%22%5D%20--%3E%20R1%0A%20%20JUMP%20--%3E%20R2%0A%20%20JUMP%20--%3E%20R3%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B('<h3 id="做市与程序化" tabindex="-1">做市与程序化 <a class="header-anchor" href="#做市与程序化" aria-label="Permalink to &quot;做市与程序化&quot;">​</a></h3><p>场内期权有做市商报价义务，微观结构与股票连续竞价不同。程序化规则仍可能覆盖报撤。研究期权微观结构要用期权行情契约，不要用股票十档去代理。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>波动率溢价：卖方收取隐含相对已实现的差，但在 A 股要扣保证金、涨跌停跳空与流动性。2015 年股市压力下，线性期货与凸性期权的保证金同时上升，保护成本在最需要时变贵——与国际危机中的 VRPs 同方向，制度细节不同。</p><p><span class="marginnote">初学者容易以为期权是「买方最多亏权利金、卖方最多赚权利金」的对称游戏。实际上卖方要交保证金且逐日盯市：行情跳空、隐含波动率飙升时保证金会上调，可能恰在最不利时刻被追保或强平——买方风险在买入时刻封顶，卖方风险账户每天重开。</span></p><p>信息：期权隐含可补充情绪与尾部，但样本短、品种少，不可把美股 VIX 产业整套搬来。50 与 300 的隐含差更多反映标的与流动性，而不是一个统一的「中国 VIX 因子」。</p>',6)),(n(),r(s,null,{default:e(()=>[o(A,{id:"mermaid-62",class:"mermaid",graph:"flowchart%20TD%0A%20%20ETF%5B%22ETF%20%E4%BB%B7%E6%A0%BC%E4%B8%8E%20IOPV%22%5D%20--%3E%20Opt%5B%22ETF%20%E6%9C%9F%E6%9D%83%22%5D%0A%20%20Fut%5B%22%E8%82%A1%E6%8C%87%E6%9C%9F%E8%B4%A7%E5%9F%BA%E5%B7%AE%22%5D%20--%3E%20Hedge%5B%22%E7%BA%BF%E6%80%A7%E5%AF%B9%E5%86%B2%22%5D%0A%20%20Opt%20--%3E%20Conv%5B%22%E5%87%B8%E6%80%A7%20%2F%20%E6%B3%A2%E5%8A%A8%E7%8E%87%22%5D%0A%20%20Limit%5B%22%E6%88%90%E5%88%86%E6%B6%A8%E8%B7%8C%E5%81%9C%22%5D%20--%3E%20Fail%5B%22%E5%AF%B9%E5%86%B2%E7%BC%BA%E8%85%BF%22%5D%0A%20%20ETF%20--%3E%20Fail%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=a("h2",{id:"边界",tabindex:"-1"},[t("边界 "),a("a",{class:"header-anchor",href:"#边界","aria-label":'Permalink to "边界"'},"​")],-1)),E[5]||(E[5]=a("p",null,"不提供操纵结算价、诱导行权或规避适当性的方法。权证、场外期权、收益凭证是不同合约。商品期权下一课。港股期权对 A 股 ETF 的交叉不是同一清算池。",-1)),E[6]||(E[6]=a("h2",{id:"小结",tabindex:"-1"},[t("小结 "),a("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),E[7]||(E[7]=a("ul",null,[a("li",null,"场内 ETF 期权把波动率从期货基差中拆出，但受涨跌停、保证金与 ETF 折溢价约束。"),a("li",null,"流动性集中；中间价不可当成交。"),a("li",null,"对冲须联立篮子可复制性；到期用交易所日历。"),a("li",null,"出处：上交所股票期权试点规则与合约细则；深交所对应规则。")],-1))])}const c=l(d,[["render",T]]);export{D as __pageData,c as default};
